SELECT channel, CASE WHEN discount >= 0.31 THEN 'high' WHEN discount >= 0.06 THEN 'mid' ELSE 'low' END discount_bucket, status, ROUND(STDDEV(discount), 2) stddev_discount FROM orders WHERE customer_id IS NULL AND status IN ('SHIPPED', 'PENDING', 'COMPLETED') GROUP BY channel, CASE WHEN discount >= 0.31 THEN 'high' WHEN discount >= 0.06 THEN 'mid' ELSE 'low' END, status HAVING ROUND(STDDEV(discount), 2) > 56 ORDER BY stddev_discount
